  `sub_kategori` enum('Jamu Cair','Jamu Bubuk','Lainnya') NOT NULL,
  `paper_type` varchar(50) NOT NULL DEFAULT 'artpaper_120',
  `paper_size` varchar(20) NOT NULL DEFAULT 'A4'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
