INSERT INTO `products` (`product_id`, `nama_produk`, `deskripsi`, `manfaat_produk`, `komposisi_produk`, `harga_produk`, `gambar_satu`, `gambar_dua`, `gambar_tiga`, `kategori`, `sub_kategori`, `paper_type`, `paper_size`) VALUES
(1, 'Jamu Kunyit Asam Madura', 'Salah satu jamu paling umum dan menyegarkan, dapat diminum oleh pria maupun wanita. Cocok untuk diminum sehari-hari, terutama untuk menjaga kesehatan dan metabolisme.', 'Meningkatkan daya tahan tubuh, Melancarkan haid, Detoksifikasi (pembersih racun dalam tubuh), Menyegarkan badan dan mengurangi bau badan', 'Kunyit, Asam jawa, Gula aren, Garam, Daun pandan', '2000.00', , NULL, NULL, 'Perawatan Kecantikan dan Tubuh', 'Jamu Bubuk', 'artpaper_120', 'A4');
INSERT INTO `products` (`product_id`, `nama_produk`, `deskripsi`, `manfaat_produk`, `komposisi_produk`, `harga_produk`, `gambar_satu`, `gambar_dua`, `gambar_tiga`, `kategori`, `sub_kategori`, `paper_type`, `paper_size`) VALUES
(2, 'Jamu Pahitan Madura', 'Rasanya pahit, namun sangat bermanfaat untuk membersihkan darah dan menjaga kesehatan kulit. Umumnya dikonsumsi oleh orang yang ingin mengatasi masalah jerawat dan gangguan kulit dari dalam.', 'Mengatasi jerawat dari dalam, Membersihkan darah, Mengurangi bau badan dan keringat berlebih, Meningkatkan sistem kekebalan tubuh', 'Sambiloto, Brotowali, Temulawak, Daun sirih, Meniran.', '2000.00', , NULL, NULL, 'Perawatan Kecantikan dan Tubuh', 'Jamu Cair', 'artpaper_120', 'A4');
INSERT INTO `products` (`product_id`, `nama_produk`, `deskripsi`, `manfaat_produk`, `komposisi_produk`, `harga_produk`, `gambar_satu`, `gambar_dua`, `gambar_tiga`, `kategori`, `sub_kategori`, `paper_type`, `paper_size`) VALUES
(3, 'Jamu Pengencang Payudara', 'Jamu luar maupun dalam yang digunakan untuk menjaga kekencangan dan bentuk payudara, terutama setelah melahirkan atau menyusui.', 'Mengencangkan dan mengangkat payudara secara alami, Mencegah payudara kendor, Menyehatkan jaringan kulit di area payudara', 'Daun sirih, Kunyit putih, Pegagan, Akar-akaran tradisional, Temu kunci', '2000.00', , , NULL, 'Reproduksi Wanita', 'Jamu Bubuk', 'artpaper_120', 'A4');
INSERT INTO `products` (`product_id`, `nama_produk`, `deskripsi`, `manfaat_produk`, `komposisi_produk`, `harga_produk`, `gambar_satu`, `gambar_dua`, `gambar_tiga`, `kategori`, `sub_kategori`, `paper_type`, `paper_size`) VALUES
(4, 'Jamu Subur Kandungan', 'Ramuan ini digunakan oleh wanita Madura sebagai cara alami untuk menjaga kesuburan dan mengatur siklus haid. Diminum secara rutin dalam periode tertentu.', 'Menyuburkan kandungan, Mengatur dan memperlancar menstruasi, Mengurangi nyeri haid, Menjaga kesehatan organ reproduksi wanita', 'Kunyit, Kencur, Temulawak, Daun sirih, Adas, Kayu manis, Madu', '2000.00', , , NULL, 'Reproduksi Wanita', 'Jamu Bubuk', 'artpaper_120', 'A4');
INSERT INTO `products` (`product_id`, `nama_produk`, `deskripsi`, `manfaat_produk`, `komposisi_produk`, `harga_produk`, `gambar_satu`, `gambar_dua`, `gambar_tiga`, `kategori`, `sub_kategori`, `paper_type`, `paper_size`) VALUES
(5, 'Jamu Tongkat Madura', 'Jamu ini merupakan salah satu produk herbal khas Madura yang paling terkenal, khususnya untuk wanita. Biasanya digunakan dalam bentuk padat (tongkat), dan dipercaya secara turun-temurun mampu menjaga kebersihan dan kesehatan organ kewanitaan.', 'Merapatkan organ intim wanita, Mengatasi keputihan, Mengurangi bau tidak sedap, Memperkuat otot kewanitaan secara alami', 'Akar kayu rapet, Daun sirih, Kunyit, Manjakani, Gaharu, Akar-akaran khas Madura', '2000.00', , , NULL, 'Reproduksi Wanita', 'Lainnya', 'artpaper_120', 'A4');
INSERT INTO `products` (`product_id`, `nama_produk`, `deskripsi`, `manfaat_produk`, `komposisi_produk`, `harga_produk`, `gambar_satu`, `gambar_dua`, `gambar_tiga`, `kategori`, `sub_kategori`, `paper_type`, `paper_size`) VALUES
(6, 'Jamu Empot-Empot', 'Ramuan tradisional yang biasa dikonsumsi pria Madura untuk menjaga vitalitas dan stamina. Sering dikonsumsi sebelum aktivitas berat atau sebagai minuman harian pria dewasa.', 'Meningkatkan stamina dan daya tahan tubuh, Mengatasi lelah dan lesu, Menambah gairah seksual secara alami', 'Jahe merah, Ginseng Jawa, Kayu manis, Cengkeh, Madu, Cabe jawa, Pasak bumi', '2000.00', , NULL, NULL, 'Vitalitas Pria', 'Jamu Bubuk', 'artpaper_120', 'A4'),
(7, 'Test', 'Tes', 'tes', 'tes', '2000.00', , NULL, NULL, 'Reproduksi Wanita', 'Jamu Bubuk', 'artpaper_120', 'A4');

